INSERT INTO public.glossary_terms
  ("id", "term", "aliases", "definition", "learnMoreUrl", "isActive", "createdAt", "updatedAt")
VALUES
  ('cg26_830221016f02a8dc83a8d4c8', 'Absolute advantage', ARRAY[]::text[], 'The ability to produce a good or service using fewer resources, or more output from the same resources, than another producer. It differs from comparative advantage, which depends on opportunity cost.', 'https://openstax.org/books/principles-economics-3e/pages/33-1-absolute-and-comparative-advantage', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_bff5582260aa958501bbe7b8', 'Absolute poverty', ARRAY[]::text[], 'Poverty assessed against a fixed benchmark of resources needed for a minimum standard of living, rather than solely against the income of others in the same society.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0d0cd7260a4645c7a3691294', 'Active investing', ARRAY['active investment strategy']::text[], 'An investment approach in which managers or investors select securities or change positions in an attempt to outperform a benchmark or meet a particular goal.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/mutual-funds-and-exchange-traded-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_bcabee5752a2b7def74cf3d4', 'Additionality', ARRAY[]::text[], 'In carbon crediting, the requirement that an emissions reduction or removal would not have occurred without the project or relevant incentive. Without additionality, a credit may not represent a genuine extra climate benefit.', 'https://ppp.worldbank.org/classification-emissions-reduction-credit', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2cb93d466b30762080e437e4', 'Alternative hypothesis', ARRAY[]::text[], 'A statement describing the effect or relationship considered if the null hypothesis is rejected, such as a difference between groups or a non-zero effect.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_3c2313e1ff441f82b946b4c1', 'Anti-dumping duty', ARRAY['anti-dumping duties']::text[], 'An additional import duty imposed following a trade-remedy investigation when dumped imports are found to injure a domestic industry under applicable rules.', 'https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b090e99b8d95f5837ec178c2', 'Asset allocation', ARRAY[]::text[], 'The distribution of an investment portfolio among broad categories such as equities, bonds and cash. It is an important driver of portfolio risk and return.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f287165794d2b9132ce7ab90', 'Asset management fee', ARRAY['management fee']::text[], 'An ongoing charge paid for managing an investment fund or portfolio, often expressed as an annual percentage of assets. Fees reduce the investor''s net return.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_80526425202994f571ac9b4d', 'Asset-liability mismatch', ARRAY[]::text[], 'A difference between the timing, interest-rate sensitivity or currency of an institution''s assets and liabilities. It can create funding or valuation risks.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_34fa73a7e98850ef09a5e177', 'Automatic stabilisers', ARRAY['automatic stabilizers']::text[], 'Features of taxes and public spending that cushion fluctuations in economic activity without new policy decisions, such as lower tax receipts and higher unemployment benefits during recessions.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_354267f38117a0c22ec9844b', 'Average total cost', ARRAY['ATC']::text[], 'A firm''s total cost divided by the number of units produced. It includes fixed and variable costs and measures average cost per unit.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_65480b6c6fed8fa9adef769b', 'Average treatment effect', ARRAY['ATE']::text[], 'The average difference between the outcome that a population would experience with an intervention and the outcome the same population would experience without it.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ef8472dfa3213b79eb8e8efb', 'Average variable cost', ARRAY['AVC']::text[], 'Total variable production cost divided by output. It measures variable cost per unit and helps firms decide whether to continue producing in the short run.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d09bfb1642c096f1535b3271', 'Balance of payments', ARRAY['BOP']::text[], 'A statistical statement of an economy''s transactions with the rest of the world, including trade, income, transfers and financial flows. Its accounts are linked through accounting identities.', 'https://www.imf.org/en/about/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4f606270797600bfeeaf9e8e', 'Bank balance sheet', ARRAY[]::text[], 'A statement of a bank''s assets, liabilities and equity. Loans and securities are major assets, while customer deposits are usually liabilities.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1af3075a17fcbf459eca20d7', 'Bank capital', ARRAY[]::text[], 'The difference between a bank''s assets and liabilities, providing a buffer against losses. Regulators also assess capital using risk-based definitions and ratios.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_04690d02d210a3a1bb43a8db', 'Bid-ask spread', ARRAY['bid-offer spread']::text[], 'The difference between the highest price a buyer is willing to pay and the lowest price a seller will accept. It is one component of trading costs.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0733acc70edb75a435a7cb3d', 'Bilateral monopoly', ARRAY[]::text[], 'A market with one dominant buyer facing one dominant seller. In labour economics it can describe a single major employer negotiating with a powerful union.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_04e45d8f5fa0c1ac3185a31f', 'Bond duration', ARRAY['modified duration']::text[], 'A measure of a bond''s sensitivity to changes in yields, related to the timing of its cash flows. Bonds with higher duration typically experience larger price changes when yields move.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2627f51fc33d2c1a7ef657b2', 'Bond maturity', ARRAY['maturity date of a bond']::text[], 'The date on which a bond''s principal is scheduled to be repaid, subject to its terms and the issuer''s ability to meet its obligations.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_05c508f48607830dc84a8fb5', 'Budget constraint', ARRAY[]::text[], 'The combinations of goods or choices a person can afford with a given income and set of prices. It captures the trade-offs imposed by limited resources.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_7643006bb4d0d81d77bdf96a', 'Capital account', ARRAY[]::text[], 'The part of the balance of payments recording certain capital transfers and transactions in non-produced, non-financial assets. It is distinct from the much larger financial account.', 'https://www.imf.org/en/about/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_766be3e508463fef0832d45a', 'Capital deepening', ARRAY[]::text[], 'An increase in the stock of physical or human capital available per worker, such as better machinery or education. It can raise output per worker.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_fa74e41b916bf2d85367b2fd', 'Capital gain', ARRAY[]::text[], 'The profit realised when an asset is sold for more than its purchase price, before relevant fees or taxes. An unsold asset can instead have an unrealised gain.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2b68c71002d683905f0178d4', 'Capital loss', ARRAY[]::text[], 'The loss realised when an asset is sold for less than its purchase price, before relevant fees or tax effects. A fall in value before sale is an unrealised loss.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_36e98472d7c8d38ff8c34d5f', 'Capital structure', ARRAY[]::text[], 'The mix of debt, equity and other financing a company uses to fund its operations and investment. Different choices affect risk, flexibility and returns.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e06021467964bfad1f0e23bc', 'Carbon credit', ARRAY['emissions reduction credit']::text[], 'A tradable unit representing a quantified reduction or removal of greenhouse gases, commonly one tonne of carbon dioxide equivalent. Its value as a climate claim depends on credible measurement and verification.', 'https://ppp.worldbank.org/classification-emissions-reduction-credit', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9b73bd219563213e716bb767', 'Carbon crediting programme', ARRAY['carbon crediting program']::text[], 'A scheme that registers eligible climate projects, checks their claimed emissions reductions or removals and issues corresponding carbon credits under a published standard.', 'https://ppp.worldbank.org/classification-emissions-reduction-credit', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ffe5aeec37a1e862a99f997f', 'Carbon dioxide removal', ARRAY['CDR']::text[], 'Activities that draw carbon dioxide from the atmosphere and store it in natural or engineered reservoirs. Removing existing atmospheric carbon differs from avoiding new emissions.', 'https://ppp.worldbank.org/emission-reduction-credits', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_94bcea1f7ff209444e310f04', 'Carbon market', ARRAY['carbon markets']::text[], 'A system in which emissions allowances or carbon credits can be traded. Some markets help firms meet legal obligations, while others operate voluntarily.', 'https://ppp.worldbank.org/emission-reduction-credits', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5754c787f10f3baaa61945e6', 'Carbon offset', ARRAY['carbon offsetting']::text[], 'The use of an emissions reduction or removal elsewhere to compensate for emissions from an activity. The credibility of an offset depends on the integrity and appropriate accounting of the underlying credit.', 'https://ppp.worldbank.org/emission-reduction-credits', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ab5612ed8f5324e8f80ba064', 'Carbon pricing', ARRAY[]::text[], 'Policies or mechanisms that place a monetary price on greenhouse gas emissions and encourage polluters to reduce them. Direct approaches include carbon taxes and emissions trading systems.', 'https://carbonpricingdashboard.worldbank.org/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a303252ebc6887ce0574189a', 'Carbon tax', ARRAY[]::text[], 'A tax on greenhouse gas emissions, generally measured per tonne of carbon dioxide equivalent. It gives emitters a financial reason to reduce their emissions.', 'https://carbonpricingdashboard.worldbank.org/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_00cb6cb82c3461f71109a35a', 'Causal inference', ARRAY[]::text[], 'The use of evidence and research design to determine whether a change in one factor causes a change in another, rather than merely being associated with it.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_fac73fd04da4efbe816600ef', 'Central bank independence', ARRAY[]::text[], 'The legal and operational ability of a central bank to make specified policy decisions without day-to-day political direction, while remaining accountable under its mandate.', 'https://www.bankofengland.co.uk/speech/2026/september/andrew-bailey-keynote-speech-at-lse-trium-anniversary-conference', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c371230c90fdcd8726d903aa', 'Central limit theorem', ARRAY['CLT']::text[], 'A result explaining why averages or sums of many sufficiently well-behaved random observations tend towards a normal distribution, even if individual observations are not normally distributed.', 'https://openstax.org/books/introductory-statistics-2e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_421c9d3a793b7adcedaf0d4d', 'Cluster sampling', ARRAY[]::text[], 'A sampling method that divides a population into groups, randomly selects some of those groups, and then surveys members within selected groups according to the study design.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_7c6db7f5d53b42b8efc1bda6', 'Co-insurance', ARRAY['coinsurance']::text[], 'An insurance arrangement under which the policyholder pays an agreed percentage of covered costs and the insurer pays the remainder, subject to the policy terms.', 'https://openstax.org/books/principles-economics-3e/pages/16-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0dda8e53332721133521470f', 'Coefficient of determination', ARRAY['R-squared', 'R²']::text[], 'A statistic describing the share of variation in an outcome explained by a fitted regression model in the sample. A high value does not by itself establish causation or good predictions.', 'https://openstax.org/books/introductory-business-statistics-2e/pages/index', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_323d20a7546d354885038852', 'Collective bargaining', ARRAY[]::text[], 'Negotiations between employers and workers represented by a trade union or another collective body over pay, working conditions and other employment terms.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_7a3dd5bc2a393d8a562a84b4', 'Command-and-control regulation', ARRAY[]::text[], 'A policy that sets specific environmental or operating requirements, such as an emissions limit or mandated technology, rather than relying mainly on price incentives.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_266af45c3a9fcf8abc19aa7e', 'Compound interest', ARRAY[]::text[], 'Interest calculated on both the original amount and interest previously earned or added to the balance. Over time it can make savings or debt grow faster than simple interest.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1696644bc648f7a8022fca9c', 'Compulsory licensing', ARRAY['compulsory licence', 'compulsory license']::text[], 'Government authorisation to use a patented invention without the owner''s permission, subject to conditions and normally compensation. WTO rules recognise this option, including for medicines.', 'https://www.wto.org/english/tratop_e/trips_e/public_health_faq_e.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f2babe56f5613b26ebd07277', 'Confidence interval', ARRAY['confidence intervals']::text[], 'A range calculated from sample data using a procedure that, over repeated samples, would contain the true parameter at a stated rate, such as 95%. It quantifies sampling uncertainty.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2e2e4c96e7f6c438d69256c3', 'Confidence level', ARRAY[]::text[], 'The long-run success rate of a confidence-interval procedure, such as 95% across repeated samples. It does not assign a probability to a fixed parameter after observing one particular interval.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e63d6bddf1dd229389b6aa5f', 'Confounding variable', ARRAY['confounder']::text[], 'A factor associated with both a proposed cause and an outcome that can create or distort an observed relationship if it is not handled in the research design.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e7068657cc5231323b736d99', 'Consumer surplus', ARRAY[]::text[], 'The benefit a consumer obtains when the price paid is below the maximum they were willing to pay for a good or service. It is one measure of the gains from exchange.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_95b5f389488a7c2242981caa', 'Contractionary fiscal policy', ARRAY[]::text[], 'A reduction in public spending or increase in taxes intended to restrain aggregate demand or narrow a fiscal deficit, other things equal.', 'https://openstax.org/books/principles-economics-3e/pages/25-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9e7e65212db3449f0ad726a9', 'Contractionary monetary policy', ARRAY['tight monetary policy']::text[], 'Central bank action intended to restrain demand and inflation by tightening financial conditions, for example through higher policy interest rates.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_388d5c23eb6b8071c1cfd964', 'Control group', ARRAY['comparison group']::text[], 'A group used as a reference when estimating the effect of an intervention. In a randomised trial it is assigned not to receive the treatment being evaluated.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_65bff45ba4a04581a6dbd088', 'Convenience sampling', ARRAY[]::text[], 'Selecting research participants because they are easy to reach rather than through a probability-based method. It can produce unrepresentative samples.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_68cc4677d9f65e69189087eb', 'Convertible bond', ARRAY[]::text[], 'A debt security whose terms permit or require conversion into shares of the issuer under specified conditions. Its price reflects both bond and equity features.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ff1be4b633c530594bcb4f38', 'Core inflation', ARRAY[]::text[], 'A measure of underlying price growth that excludes selected volatile items, commonly food and energy. It helps analysts distinguish persistent inflation from temporary price shocks.', 'https://openstax.org/books/principles-economics-3e/pages/22-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0e0829fd45ad575854d8ed45', 'Corporate bond', ARRAY[]::text[], 'A debt security issued by a company to borrow funds. Investors typically receive interest payments and a promise of principal repayment, subject to the issuer''s ability to pay.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1a58bbaa6a18a5e8511d2c23', 'Correlation coefficient', ARRAY[]::text[], 'A numerical measure of the strength and direction of an association between two variables. Pearson''s correlation ranges from minus one to one for linear relationships.', 'https://openstax.org/books/introductory-business-statistics-2e/pages/index', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_880d656481ff906beb4b4bd4', 'Cost-of-living adjustment', ARRAY['COLA', 'cost of living adjustment']::text[], 'An increase in wages, benefits or other payments linked to a measure of inflation. Its purpose is to protect purchasing power as prices change.', 'https://openstax.org/books/principles-economics-3e/pages/22-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8c012cfb7dc457d38a456836', 'Counterfactual', ARRAY['counterfactual outcome']::text[], 'What would have happened to a person, firm or economy if a particular policy or event had not occurred. Comparing actual outcomes with a credible counterfactual is central to impact evaluation.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_eb55d2d75cba28f80ff6907e', 'Counterparty risk', ARRAY[]::text[], 'The possibility that the other party to a financial contract fails to meet its obligations, causing a financial loss.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a1c7c1a541a371aea58e3759', 'Countervailing duty', ARRAY['countervailing duties']::text[], 'An import duty used to offset certain subsidies benefiting foreign producers, where the legal conditions for a countervailing measure are met.', 'https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0137315067eae919cc0aaa17', 'Coupon rate', ARRAY[]::text[], 'The stated interest rate on a bond applied to its face value to determine scheduled coupon payments. It differs from the bond''s current yield or yield to maturity.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_dfa224f92245870da3166e09', 'Credit rating', ARRAY[]::text[], 'An assessment of an issuer''s or security''s relative creditworthiness, often expressed as a letter grade. It is an opinion about credit risk, not a guarantee of repayment.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_630e5610943fb30f06ffadf2', 'Credit spread', ARRAY[]::text[], 'The difference in yield between a debt instrument and a comparable lower-risk reference bond. Wider spreads often reflect greater perceived default or liquidity risk.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c54ff75d86e0ac8c26b37384', 'Cross-price elasticity of demand', ARRAY[]::text[], 'The percentage change in demand for one good divided by the percentage change in another good''s price. Positive values suggest substitutes; negative values suggest complements.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_27b8dc0466d8d358acc2bfa3', 'Currency appreciation', ARRAY[]::text[], 'A rise in the value of one currency relative to another under a floating exchange rate. It makes foreign goods cheaper in domestic currency terms, other things equal.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1d3490f63837193ca5bf8aee', 'Currency depreciation', ARRAY[]::text[], 'A fall in the value of one currency relative to another under a floating exchange rate. It tends to make imports dearer and exports more competitive, other factors equal.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2fc56153c6a40bb77d9581df', 'Currency peg', ARRAY['pegged exchange rate']::text[], 'A policy under which authorities seek to keep a currency''s value at or near a specified rate against another currency or basket. Defending a peg can constrain monetary policy.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f67be68486149ebe81c77e43', 'Currency union', ARRAY[]::text[], 'An arrangement in which multiple economies share a currency and usually a common monetary authority, surrendering independent national exchange-rate policy.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5f1e7d088ddd4b236107a638', 'Cyclical unemployment', ARRAY[]::text[], 'Joblessness caused by weakness in overall economic activity. It tends to rise during recessions and fall as demand and employment recover.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c23013a0a401a2d85e2d5ab2', 'Deadweight loss', ARRAY[]::text[], 'Potential gains from trade that are lost when a market produces or exchanges an inefficient quantity. Unlike a transfer between buyers and sellers, this lost surplus benefits no one.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c769c3bd6c7b8118762ee799', 'Debt financing', ARRAY[]::text[], 'Raising funds by borrowing, with an obligation to repay principal and usually interest. It differs from issuing ownership stakes to investors.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_761f90c820ae855ff85fcbf9', 'Debt sustainability', ARRAY[]::text[], 'Whether a borrower can continue servicing its obligations without unrealistic adjustments or a disruptive loss of market access. Assessments depend on interest costs, growth and future budgets.', 'https://www.imf.org/en/publications/fandd/issues/2022/12/basics-what-is-sovereign-debt', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2707f7fcef3946d6657c960a', 'Debt-to-GDP ratio', ARRAY[]::text[], 'Outstanding public debt expressed as a percentage of annual gross domestic product. It compares government debt with the size of the economy, but is not a complete measure of repayment risk.', 'https://www.imf.org/en/publications/fandd/issues/2022/12/basics-what-is-sovereign-debt', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_59dc7c1b5d2ad5d93fd62a6d', 'Default risk', ARRAY[]::text[], 'The possibility that a borrower or bond issuer fails to make promised interest or principal payments. It is a key component of credit risk.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8db31aa2c738b6e88255246f', 'Deposit insurance', ARRAY[]::text[], 'A scheme that protects eligible depositors up to specified limits if a covered bank fails. It helps safeguard savings and reduce incentives for bank runs.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_045197042299119bc2c0a8f3', 'Difference-in-differences', ARRAY['DiD', 'difference in differences']::text[], 'A method that compares changes in outcomes over time between a treated group and a comparison group. It commonly relies on the assumption that their untreated trends would have been parallel.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1e2bf1d16c8a4b925d0bfa78', 'Diminishing marginal utility', ARRAY['law of diminishing marginal utility']::text[], 'The tendency for each extra unit of a good consumed to provide less additional satisfaction than the previous unit, over a relevant range of consumption.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0fc817d88d5e1fb3855182e8', 'Discount rate', ARRAY[]::text[], 'The rate used to convert future money or benefits into a present value. A higher discount rate reduces the present value of otherwise identical future payments.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2d25ca281c31a6e880073033', 'Discouraged workers', ARRAY[]::text[], 'People who want a job but have stopped looking because they believe no suitable work is available. They are generally not counted as unemployed under standard survey definitions.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_223bbb482ad3eb470d8547cd', 'Diseconomies of scale', ARRAY[]::text[], 'A rise in long-run average production cost as a firm expands. Increasing management complexity or coordination costs can outweigh the advantages of a larger scale.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_7cae44f2b4d0272a242d0dde', 'Disposable income', ARRAY[]::text[], 'Income available to households after direct taxes and relevant deductions, sometimes also including cash transfers depending on the statistical measure.', 'https://openstax.org/books/principles-economics-3e/pages/25-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6df497b4bf909db09f1a36ae', 'Dividend', ARRAY[]::text[], 'A payment made by a company to shareholders, often from profits. Dividends are not guaranteed and can be increased, reduced or suspended.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_206c2e8cc12a4f796ed70110', 'Dividend yield', ARRAY[]::text[], 'Annual dividends per share divided by the current share price, expressed as a percentage. It measures cash distributions relative to price but does not guarantee future dividends.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_3930478f71dbecd0ca1e8356', 'Dollar-cost averaging', ARRAY['pound-cost averaging']::text[], 'Investing a fixed amount at regular intervals regardless of market prices. It spreads purchases over time but does not eliminate investment risk.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_70d71a5c1bd3411ad5b543ec', 'Dollarisation', ARRAY['dollarization']::text[], 'The use of a foreign currency, usually the US dollar, alongside or instead of a domestic currency for payments, savings or prices. Full dollarisation removes an independent national currency.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_35385cd2572f30bd1c10636c', 'Double counting of emissions reductions', ARRAY[]::text[], 'The recording or use of the same greenhouse-gas reduction or removal more than once toward climate targets or claims. Credible carbon markets need accounting rules to prevent it.', 'https://ppp.worldbank.org/classification-emissions-reduction-credit', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2b186868083338833f900dbc', 'Earnings per share', ARRAY['EPS']::text[], 'A company''s profit attributable to ordinary shareholders divided by the weighted average number of ordinary shares outstanding. It is widely used in equity valuation.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a287be6c4d179c723d9fae7c', 'Economic convergence', ARRAY['income convergence']::text[], 'A tendency for poorer economies to grow faster than richer ones and narrow their income-per-person gap, when the conditions for catching up are present.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2cab24a82fa96ea23e4955a4', 'Economic profit', ARRAY[]::text[], 'A firm''s revenue minus both its explicit expenses and the opportunity costs of resources it already owns. It can be lower than accounting profit.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4f4d56219610c3ace70bea4b', 'Effective lower bound', ARRAY['ELB']::text[], 'The level below which further policy rate cuts become difficult or less effective because people can hold cash and financial intermediation faces constraints. It need not be exactly zero.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_950c2d9b68d749c9a45c1f9d', 'Efficiency wage', ARRAY['efficiency wages']::text[], 'A wage paid above the market-clearing level because an employer expects it to improve productivity, retention or effort. The approach may also contribute to unemployment.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ec9b2f357e67aff57b17a991', 'Emissions trading system', ARRAY['emissions trading scheme', 'ETS']::text[], 'A policy requiring covered emitters to surrender tradable allowances for their emissions. In a cap-and-trade scheme, the total number of allowances is limited to help achieve an emissions target.', 'https://carbonpricingdashboard.worldbank.org/', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d51f7bbc939774e1000b831f', 'Endogeneity', ARRAY[]::text[], 'A problem arising when an explanatory variable is correlated with unobserved influences on the outcome, making a simple regression coefficient unreliable as a causal estimate.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4f7ee493f3597917f5f5872c', 'Equity financing', ARRAY[]::text[], 'Raising capital by issuing ownership interests rather than taking on debt. It can dilute existing owners but does not require fixed interest payments.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_06f06e8b30f11b5e0bbadfda', 'Exchange-traded fund', ARRAY['ETF']::text[], 'An investment fund whose shares trade on an exchange during the day. It holds a portfolio of assets, often tracks an index, and gives investors access through one tradable security.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/exchange-traded-fund-etf', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a0b421814ab738cef8ddc170', 'Expansionary fiscal policy', ARRAY[]::text[], 'An increase in public spending or reduction in taxes intended to support aggregate demand, other things equal. Its effects depend on financing and economic conditions.', 'https://openstax.org/books/principles-economics-3e/pages/25-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a020baf9dffc5154ff24b15e', 'Expansionary monetary policy', ARRAY['loose monetary policy']::text[], 'Central bank action intended to ease financial conditions and support spending and economic activity, such as lowering interest rates or buying assets.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_bf744843bbe3d0018efc41c8', 'Fiat money', ARRAY[]::text[], 'Currency that is not convertible into a fixed amount of a commodity such as gold and whose use rests on legal, institutional and public confidence rather than intrinsic value.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5fec0e5194ae812bc3ab4e32', 'Financial account', ARRAY[]::text[], 'The balance-of-payments account recording cross-border acquisitions and disposals of financial assets and liabilities, including direct investment, portfolio investment and reserves.', 'https://www.imf.org/en/about/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ce1788a92c65279ec373e65f', 'Financial intermediary', ARRAY[]::text[], 'An institution that channels funds between savers and borrowers or investors, such as a bank or investment fund. Intermediaries help manage payments, risks and information.', 'https://openstax.org/books/principles-economics-3e/pages/27-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6dbeafeab99e0e2d045cad17', 'Fiscal consolidation', ARRAY['fiscal adjustment']::text[], 'Policy changes intended to reduce a government''s deficit or stabilise public debt, usually through spending restraint, revenue measures or both.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d7e028d434621e884e554592', 'Fiscal rule', ARRAY['fiscal rules']::text[], 'A lasting constraint on government fiscal policy, such as a numerical ceiling on debt, deficits or spending, intended to support sustainable public finances.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c8704c57641c2df7d74333f6', 'Fiscal space', ARRAY[]::text[], 'The room a government has to increase spending or cut taxes without undermining its access to financing or the sustainability of public debt.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_838f79f74f0c6b52af8f247d', 'Fiscal sustainability', ARRAY['sustainable public finances']::text[], 'The ability of a government to meet its obligations over time without requiring implausibly large future adjustments or default.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d9bfde32121d1268b9d71b4d', 'Fixed cost', ARRAY[]::text[], 'A production expense that does not vary with output over the relevant period, such as rent on a fixed lease. It may be incurred even when production stops.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8ca3013c8892fb4e339f4118', 'Floating exchange rate', ARRAY[]::text[], 'A currency regime in which the exchange rate is chiefly determined by supply and demand in foreign-exchange markets rather than a fixed official peg.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_84c53e99fb13173f24e6cc68', 'Foreign direct investment', ARRAY['FDI']::text[], 'An investment involving a lasting interest and meaningful influence in a business abroad, commonly defined using at least a 10% voting stake. It differs from simply buying foreign securities.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0b63c80e7a6b6bfe36297a83', 'Foreign exchange intervention', ARRAY[]::text[], 'Central bank purchases or sales of currencies intended to affect exchange-rate conditions or market functioning. Intervention can influence the currency without changing a formal peg.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_392e3672a639b0a0ccedc0c5', 'Foreign exchange market', ARRAY['FX market']::text[], 'The global market in which participants buy and sell currencies. Exchange rates respond to trade, capital flows, expectations and monetary conditions.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_248721d58c5e858e33113123', 'Foreign portfolio investment', ARRAY[]::text[], 'Cross-border purchases of financial securities, such as shares and bonds, without the lasting managerial influence associated with direct investment.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_dbef0819e5953165deee04e2', 'Forward guidance', ARRAY[]::text[], 'Communication by a central bank about the likely future direction of monetary policy. It aims to shape expectations of interest rates and broader financial conditions.', 'https://www.ecb.europa.eu/ecb-and-you/explainers/tell-me/html/what-is-forward_guidance.em.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_26721e343f597247c650e317', 'Free trade agreement', ARRAY['FTA']::text[], 'An agreement under which two or more economies reduce or remove barriers to trade between them, often with rules governing which goods qualify for preferential tariffs.', 'https://openstax.org/books/principles-economics-3e/pages/34-4-how-governments-enact-trade-policy-globally-regionally-and-nationally', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_115f8f188dcc9381fed5e0d9', 'Free-rider problem', ARRAY['free rider problem']::text[], 'An incentive to benefit from a shared good or activity without contributing to its cost. It can lead private markets to provide too little of a public good.', 'https://openstax.org/books/principles-economics-3e/pages/13-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1ef58fa5ff72795a7a614218', 'Frictional unemployment', ARRAY[]::text[], 'Short-term unemployment while people move between jobs, search for suitable work or enter the labour force. Some frictional unemployment exists even in a healthy economy.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c932f25374f5bf87261c250a', 'GDP deflator', ARRAY[]::text[], 'A price index covering the final goods and services included in GDP. It allows nominal GDP to be adjusted into real GDP.', 'https://openstax.org/books/principles-economics-3e/pages/19-2-adjusting-nominal-values-to-real-values', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_60762fb7cc6a55138e611c6c', 'GDP per capita', ARRAY[]::text[], 'A country''s gross domestic product divided by its population. It gives a rough measure of economic output per person, though it does not show how income is distributed or how people live.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4d27a723e04062113c81d622', 'Hard currency peg', ARRAY['hard peg']::text[], 'An exchange rate arrangement in which authorities commit to a fixed exchange rate or a tightly defined mechanism, leaving limited room for independent monetary policy.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0f0ddfcc7e34881fd1c0cb9c', 'Hedge fund', ARRAY[]::text[], 'A privately offered pooled investment vehicle that may use strategies such as leverage, short selling and derivatives. Its legal structure and investment restrictions vary by jurisdiction.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/private-investment-funds/hedge-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_303bd36d40ddf86accab4c1e', 'High-yield bond', ARRAY['junk bond', 'high-yield bonds']::text[], 'A bond assessed as below investment grade, usually offering a higher yield to compensate investors for greater risk of default or other losses.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_24bb86d62cfd2d7ae2948a19', 'Hypothesis testing', ARRAY[]::text[], 'A formal procedure that uses sample evidence to assess a claim about a population or model, balancing the risks of rejecting a true null hypothesis and overlooking a false one.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6375d36f5170aeb31c47dd68', 'Import quota', ARRAY['import quotas']::text[], 'A quantitative limit on the amount of a good that can be imported during a specified period. Quotas restrict supply and can raise prices for domestic buyers.', 'https://openstax.org/books/principles-economics-3e/pages/34-1-protectionism-an-indirect-subsidy-from-consumers-to-producers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_65eb50c7bf81c8300cca5550', 'Import substitution', ARRAY['import substitution industrialisation', 'import substitution industrialization']::text[], 'A development strategy that promotes domestic production of goods previously imported, typically using protection or industrial policy. Its benefits and costs depend on implementation.', 'https://openstax.org/books/principles-economics-3e/pages/34-1-protectionism-an-indirect-subsidy-from-consumers-to-producers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_992bd04587d0ee9594fe474f', 'Income effect', ARRAY[]::text[], 'The change in a consumer''s chosen quantities caused by a change in purchasing power while relative prices are held constant. It can reinforce or offset the substitution effect.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2dd0aea01f9fe659d6b1d530', 'Income elasticity of demand', ARRAY[]::text[], 'The percentage change in demand for a good divided by the percentage change in consumer income. This helps distinguish normal goods from inferior goods.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_af7ea6dedcd1d038cb87717b', 'Income inequality', ARRAY[]::text[], 'Differences in income received by individuals or households. Measures of inequality describe how income is distributed across a population, not merely its overall average.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_308c9dfb714d20b5ba3f4f33', 'Income redistribution', ARRAY['redistributive policy']::text[], 'Policies that change how resources are distributed across households, often through taxes, cash transfers and public services. They can reduce post-tax income inequality.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_231051fc7edaa864c4096c36', 'Index fund', ARRAY[]::text[], 'A fund designed to track the performance of a specified market index rather than selecting individual assets to outperform it. Tracking is not always exact.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/mutual-funds-and-exchange-traded-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_43744600f57dba9b1e5973b9', 'Inferior good', ARRAY[]::text[], 'A good for which demand tends to fall as consumer income increases, other things equal. Better-off consumers may switch to alternatives they prefer.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_28fb77a60b8c34f1f3f94d4a', 'Inflation expectations', ARRAY[]::text[], 'Beliefs about how quickly prices will rise in the future. They can influence wage bargaining, spending decisions and the effectiveness of monetary policy.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_78928bdff62188f5e18b146d', 'Inflation risk premium', ARRAY[]::text[], 'Extra compensation investors may demand for uncertainty about future inflation, particularly when holding long-term assets with fixed nominal payments.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ac6bbfad6482d6daadff3971', 'Inflation targeting', ARRAY[]::text[], 'A monetary policy strategy under which a central bank announces an inflation objective and adjusts policy to keep inflation near it over time.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_72172ac235f5618bdd9b899d', 'Information asymmetry in healthcare', ARRAY[]::text[], 'A situation in which patients, providers or insurers possess different information about medical needs, treatment quality or risk, complicating choices and contracts.', 'https://openstax.org/books/principles-economics-3e/pages/16-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8c176ac377024bc6a802571a', 'Initial public offering', ARRAY['IPO']::text[], 'The first sale of a company''s shares to public investors, typically associated with a stock-market listing. It can raise capital or enable existing owners to sell shares.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/initial-public-offering-ipo', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_91ad876917ebfff0b84b010f', 'Instrumental variable', ARRAY['instrumental variables']::text[], 'A variable used to identify a causal effect when the explanatory variable is endogenous. A valid instrument affects the outcome through the variable of interest and satisfies additional identifying assumptions.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_af23fd8322dfa9aea53ea6b2', 'Insurance deductible', ARRAY['deductible in insurance']::text[], 'The amount a policyholder must pay for covered expenses before the insurer begins paying under the policy''s terms.', 'https://openstax.org/books/principles-economics-3e/pages/16-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a66b036b84f077007c87eaf7', 'Insurance premium', ARRAY[]::text[], 'A payment made for insurance coverage, typically at regular intervals. Its level depends on the insured risk, policy conditions and other pricing factors.', 'https://openstax.org/books/principles-economics-3e/pages/16-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_428700a65bcabd5735ce1955', 'Intellectual property', ARRAY['intellectual property rights']::text[], 'Legal rights protecting certain inventions and creative works, including patents, copyright, trade marks and trade secrets. They can encourage investment in ideas while restricting others'' use.', 'https://openstax.org/books/principles-economics-3e/pages/13-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_814e2c95e08996ecafd57e84', 'Intention-to-treat effect', ARRAY['ITT effect']::text[], 'The effect of being assigned or offered an intervention, whether or not participants actually take it up. It preserves the original random assignment in an experiment.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ceed8229424502cb6f97c33b', 'Internal rate of return', ARRAY['IRR']::text[], 'The discount rate at which a project''s net present value equals zero. It is one measure used to compare investments, though it can be misleading for unusual cash-flow patterns.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_94f3b130202cde16615cbafe', 'International capital flows', ARRAY[]::text[], 'Movements of investment or financing across national borders, including direct investment and purchases or sales of foreign financial assets.', 'https://openstax.org/books/principles-economics-3e/pages/29-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6ddfb596fa114b2bbbbef246', 'Intra-industry trade', ARRAY[]::text[], 'International trade in similar types of goods within the same industry, such as cars imported and exported by two countries. Product variety and scale economies can help explain it.', 'https://openstax.org/books/principles-economics-3e/pages/33-1-absolute-and-comparative-advantage', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_bc223e1e959be1d7935bc332', 'Investment-grade bond', ARRAY[]::text[], 'A bond rated at or above a specified credit-quality threshold by recognised rating agencies. It is generally considered less likely to default than speculative-grade debt.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_59bd96ecbf6fd11f9e552036', 'Labour force participation rate', ARRAY['labor force participation rate']::text[], 'The proportion of working-age people who are employed or actively seeking work, under the statistical definition used. It differs from the employment and unemployment rates.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4ea227090e810759e25a5169', 'Labour market discrimination', ARRAY['labor market discrimination']::text[], 'Unequal treatment of workers in hiring, pay or promotion for reasons unrelated to their productivity, such as discrimination based on sex or ethnicity.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6bb4f552a456f3359c4205f0', 'Labour market monopsony', ARRAY['labor market monopsony']::text[], 'A situation in which an employer has substantial power over the wages it pays because workers have few comparable employment alternatives.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f4bb3c7270e79c1645ab1aba', 'Labour productivity', ARRAY['labor productivity']::text[], 'Output produced per worker or per hour worked. Growth in labour productivity is an important source of higher wages and long-term improvements in living standards.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_cc0ab698e70ce5353d083334', 'Limit order', ARRAY[]::text[], 'An instruction to buy or sell a security only at a specified price or better. It controls the acceptable price but may remain unfilled.', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_3856580b964b6210f2cc07dc', 'Linear regression', ARRAY[]::text[], 'A statistical method for modelling how an outcome varies with one or more explanatory variables under a specified linear relationship. Its coefficients are not automatically causal effects.', 'https://openstax.org/books/introductory-business-statistics-2e/pages/index', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_31f1463b82f6ea08522a5e73', 'Logrolling', ARRAY[]::text[], 'An exchange of political support in which legislators agree to back one another''s proposals, sometimes allowing a package of policies to pass that none would secure alone.', 'https://openstax.org/books/principles-economics-3e/pages/18-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_72e65821ac7c72eae150e966', 'Lorenz curve', ARRAY[]::text[], 'A graph showing the cumulative share of income or wealth held by the poorest successive shares of a population. A curve further below the equality line indicates greater inequality.', 'https://databank.worldbank.org/metadataglossary/world-development-indicators/series/SI.POV.GINI', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_97fe1916484e31a9effbd530', 'Margin call', ARRAY[]::text[], 'A broker''s demand for additional cash or securities when a leveraged account falls below required collateral or maintenance-margin levels.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b768bac6ccfdff17f09bd61e', 'Marginal cost', ARRAY['MC']::text[], 'The additional expense of producing one more unit of output. Firms compare marginal cost with marginal revenue when deciding how much to produce.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_7d272fe5ead5543d8e9a71b4', 'Marginal effective tax rate', ARRAY['METR']::text[], 'The proportion of an additional amount of earnings lost through higher taxes and reduced benefits. It can be high even when the headline income-tax rate is low.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d4f1b4e73a0054ecdb0d8fa0', 'Marginal product', ARRAY[]::text[], 'The additional output resulting from one more unit of an input, such as labour, while other inputs are held fixed. It helps explain firms'' hiring decisions.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5e8828eb3f5631b77c3b13c7', 'Marginal revenue', ARRAY['MR']::text[], 'The extra revenue earned from selling one additional unit of output. A profit-maximising firm generally increases production while this exceeds marginal cost.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a5d2232eee8aaddc27fa296b', 'Marginal revenue product of labour', ARRAY['marginal revenue product of labor']::text[], 'The extra revenue a firm earns by employing one additional unit of labour, holding other inputs fixed. It helps determine firms'' willingness to pay for workers.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_97622af27f2da3ae65fb2167', 'Market capitalisation', ARRAY['market capitalization', 'market cap']::text[], 'The market value of a company''s outstanding shares, calculated as its current share price multiplied by the number of shares outstanding. It measures equity value, not total enterprise value.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d72a5aeb25ab4f0e99ba9114', 'Market maker', ARRAY[]::text[], 'A firm that regularly quotes prices at which it will buy or sell a security. Market makers provide liquidity and help investors trade.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1dedcb972d4799240efaa081', 'Market order', ARRAY[]::text[], 'An instruction to buy or sell a security promptly at the best available prices. Execution is generally prioritised over obtaining an exact price.', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_744e05fd63e18975b35f935e', 'Means-tested benefit', ARRAY['means-tested benefits']::text[], 'A public payment or service for which eligibility or payment size depends on a person''s income, wealth or other assessed resources.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_db110cc57dd08e989e472903', 'Median voter theorem', ARRAY['median voter theory']::text[], 'In a simple majority-voting model with a single policy dimension and particular assumptions, competition can push candidates toward the preference of the median voter.', 'https://openstax.org/books/principles-economics-3e/pages/18-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e6182026ae68774e458d6623', 'Merchandise trade balance', ARRAY[]::text[], 'The value of a country''s exports of goods minus its imports of goods. It excludes services, so it differs from the overall trade balance.', 'https://openstax.org/books/principles-economics-3e/pages/23-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_77dd7b961694c69f06a4ac8d', 'Minimum wage', ARRAY[]::text[], 'A legally required floor on pay for covered workers. Its effects on employment and earnings depend partly on the labour market and the level at which it is set.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_75c0a695b8f8aa89a15e2d65', 'Monetary base', ARRAY['base money']::text[], 'Currency in circulation plus balances commercial banks hold at the central bank, subject to the precise national definition. It is sometimes called high-powered money.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8427f38e3c4c73f16bc1b690', 'Monetary policy transmission mechanism', ARRAY[]::text[], 'The channels through which central bank decisions affect market interest rates, credit, exchange rates, spending and ultimately inflation and output.', 'https://www.ecb.europa.eu/services/glossary/html/glossi.en.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_00911abf0eac3c9a815bd90e', 'Most-favoured-nation treatment', ARRAY['MFN treatment']::text[], 'A WTO principle requiring a member generally to extend a trade advantage granted to one trading partner to other WTO members, subject to permitted exceptions.', 'https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_cad9352765169b5837281b7f', 'Mutual fund', ARRAY['mutual funds']::text[], 'An investment vehicle that pools investors'' money and holds a portfolio of securities or other assets, managed according to an investment strategy.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/mutual-funds-and-exchange-traded-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_3cca8e97842879b17fb2b7dd', 'National saving and investment identity', ARRAY[]::text[], 'An accounting relationship linking domestic saving, investment, the government budget and the external balance. It shows how financing needs must be met from domestic or foreign saving.', 'https://openstax.org/books/principles-economics-3e/pages/23-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2db62e54d71caf894b93338c', 'National treatment in trade', ARRAY[]::text[], 'A trade rule requiring imported products, once they have entered the domestic market, to be treated no less favourably than comparable domestic products in relevant internal measures.', 'https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_eb4506699ec2c5a58cf76d9f', 'Natural experiment', ARRAY[]::text[], 'A situation where events or institutions create differences in exposure resembling an experiment, enabling causal analysis when the source of variation is sufficiently credible.', 'https://www.worldbank.org/en/about/unit/unit-dec/impactevaluation/dime-research', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0fc0331b94589379af5c1e5d', 'Natural rate of unemployment', ARRAY[]::text[], 'The unemployment rate consistent with an economy operating normally rather than in a recession, reflecting job turnover and structural labour-market frictions.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_213638372cf1190e72a307fd', 'Negative externality', ARRAY[]::text[], 'A cost imposed on people outside a transaction that buyers and sellers do not fully account for. Air pollution is a common example.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_82ddc83172c83d29c588db52', 'Net present value', ARRAY['NPV']::text[], 'The present value of a project''s expected cash inflows minus the present value of its costs, using a chosen discount rate. A positive value suggests the project adds value under the assumptions.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9555dd434b931203e71de841', 'Nominal GDP', ARRAY[]::text[], 'The value of final goods and services produced in an economy measured at current prices. It can rise because production grows, prices increase, or both.', 'https://openstax.org/books/principles-economics-3e/pages/19-2-adjusting-nominal-values-to-real-values', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_49c3aa0f85ef0ff24e7468b6', 'Non-excludability', ARRAY['non-excludable good']::text[], 'A property of a good for which it is difficult or costly to prevent people from benefiting, even if they do not pay. It is one characteristic of a pure public good.', 'https://openstax.org/books/principles-economics-3e/pages/13-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d41330178f4a13c804f720ae', 'Non-rivalry', ARRAY['non-rival consumption']::text[], 'A property of a good whose use by one person does not significantly reduce the amount available to others. It is one characteristic of a pure public good.', 'https://openstax.org/books/principles-economics-3e/pages/13-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b4a14c7f5415501893b8d979', 'Non-tariff barrier', ARRAY['non-tariff barriers']::text[], 'A restriction on international trade other than a tariff, such as an import quota, licensing requirement or technical rule. Some such measures also serve legitimate public-policy objectives.', 'https://openstax.org/books/principles-economics-3e/pages/34-4-how-governments-enact-trade-policy-globally-regionally-and-nationally', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_36b018ff5bd195f0e472ef7d', 'Normal distribution', ARRAY['Gaussian distribution']::text[], 'A symmetric, bell-shaped probability distribution described by its mean and standard deviation. It is widely used in statistical modelling and inference.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_12273ab56dd816f82f833931', 'Normal good', ARRAY[]::text[], 'A good for which demand tends to rise as consumer income increases, other things equal. Most everyday products are normal goods over a relevant income range.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_27fb62330c534254889f6482', 'Null hypothesis', ARRAY[]::text[], 'The statement being tested statistically, often that a parameter equals a specified value or that an intervention has no effect. The data are assessed for evidence against it.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b1664cf10800e7c8a1a2ccfb', 'Occupational licensing', ARRAY[]::text[], 'A legal requirement that someone obtain official permission or professional credentials before practising certain occupations. It can protect consumers but also restrict entry.', 'https://openstax.org/books/principles-economics-3e/pages/16-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c8c353b67c1a0cae63084473', 'Omitted variable bias', ARRAY[]::text[], 'Distortion in an estimated relationship caused by leaving out a relevant factor that affects the outcome and is associated with an included explanatory variable.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b5ed7b1db90ad215e2b2dd72', 'Open market operations', ARRAY[]::text[], 'Central bank purchases or sales of financial assets, commonly government securities, to influence liquidity and short-term interest rates.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_507b648879c3ceb92e4aed53', 'p-value', ARRAY[]::text[], 'The probability, assuming a specified null hypothesis and model, of obtaining a test statistic at least as extreme as the one observed. It is not the probability that the null hypothesis is true.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_78323327883016cbdcfb8002', 'Parallel trends assumption', ARRAY[]::text[], 'The assumption in difference-in-differences analysis that, without the intervention, treated and comparison groups would have experienced similar changes in the outcome over time.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5540e9136c91e75304d206e0', 'Passive investing', ARRAY['passive investment strategy']::text[], 'An approach that seeks to follow a market index or predefined rules with relatively little active security selection. Costs and tracking error still matter.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/mutual-funds-and-exchange-traded-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e1fd8b7ad4f0cfa9a8a23dc1', 'Patent', ARRAY['patent protection']::text[], 'A time-limited exclusive legal right granted for a qualifying invention. It usually permits the owner to prevent others from making, using or selling that invention without consent, subject to national law.', 'https://openstax.org/books/principles-economics-3e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d0206c292344d7fc1fbe0dca', 'Physical capital', ARRAY[]::text[], 'Produced assets used to make goods and services, such as machinery, buildings and transport infrastructure. It is distinct from financial capital, which represents funds or claims.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9b0be88f3ffd6750b349a3fd', 'Pigouvian tax', ARRAY['Pigovian tax']::text[], 'A tax designed to reflect the external cost of an activity, bringing private incentives closer to the wider social cost. A pollution tax is a common example.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6b6693d75a22b95d1b11635b', 'Placebo', ARRAY[]::text[], 'A treatment without the active component being tested, used in some studies to separate the intervention''s effects from expectations or other influences.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0bf7d9001dc2c47eaa814056', 'Pork-barrel spending', ARRAY[]::text[], 'Public expenditure directed towards a particular constituency or district, often to deliver locally visible benefits rather than necessarily maximise national welfare.', 'https://openstax.org/books/principles-economics-3e/pages/18-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c52541691ef1ff144e5f3c78', 'Portfolio diversification', ARRAY[]::text[], 'Spreading investments across assets or sources of risk instead of relying on a single holding. It can reduce company-specific risk but cannot eliminate market-wide risk.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_036676ff0eecf99efe0f7a93', 'Positive externality', ARRAY[]::text[], 'A benefit to people outside a transaction that the parties making the decision do not fully account for. Vaccination or research can create positive spillovers.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_babddfc10317d7c2a53c33a0', 'Poverty line', ARRAY[]::text[], 'An income or consumption threshold used to determine whether people are considered poor. Thresholds vary by country and may be absolute or relative.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c177713986dac831dc06c28e', 'Poverty rate', ARRAY[]::text[], 'The proportion of a population living below a specified poverty threshold. Its meaning depends on how that threshold and household resources are defined.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f62e76d421ccdb6ceb56db89', 'Poverty trap', ARRAY[]::text[], 'A situation in which economic or institutional forces make it difficult to escape low income. One example occurs when additional earnings cause benefits to fall sharply, limiting the gain from work.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2f0edf4a66e513ed9f3f90cf', 'Preferential trade agreement', ARRAY[]::text[], 'A trade arrangement granting participating economies better access or lower barriers than those available to non-participants, within the rules applicable to the arrangement.', 'https://openstax.org/books/principles-economics-3e/pages/34-4-how-governments-enact-trade-policy-globally-regionally-and-nationally', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_85df28a88fbd566954b23400', 'Present value', ARRAY['discounted present value']::text[], 'The value today of money expected in the future, calculated by discounting future payments at an appropriate rate. It reflects the time value of money.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_37ef07733dc2e44d3e923be6', 'Price elasticity of demand', ARRAY['PED']::text[], 'The percentage change in quantity demanded divided by the percentage change in price. It measures how sensitive buyers are to price changes, other factors held constant.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_5d81a25aeec9254a5595f1af', 'Price elasticity of supply', ARRAY['PES']::text[], 'The percentage change in quantity supplied divided by the percentage change in price. It measures how easily producers adjust output when market prices change.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ba291b03b27ba3c9226a643c', 'Price-to-earnings ratio', ARRAY['P/E ratio']::text[], 'A valuation measure calculated by dividing a company''s share price by its earnings per share. It shows the price investors pay for each unit of annual reported earnings.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_02543ab6e86b4aafeb53bd06', 'Primary budget balance', ARRAY['primary balance']::text[], 'Government revenue minus spending excluding interest payments on existing debt. It helps separate current fiscal decisions from the cost of past borrowing.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_982658c9a492583271643fcc', 'Private cost', ARRAY[]::text[], 'A cost borne directly by the person or organisation taking an economic action. It does not include costs shifted onto unrelated third parties.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8d6bab55074f7d2eb8e03fed', 'Private equity', ARRAY['private equity investment']::text[], 'Investment in companies whose shares are not publicly traded, often involving an active role in ownership, operations or restructuring.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/private-investment-funds/private-equity', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9b3b59e8bae9695c4d13a820', 'Producer price index', ARRAY['PPI']::text[], 'An index measuring changes in prices received by producers or paid for inputs, depending on its definition. It helps track price pressures earlier in the supply chain.', 'https://openstax.org/books/principles-economics-3e/pages/22-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a4c8ad5b59fd525039119d75', 'Producer surplus', ARRAY[]::text[], 'The benefit a producer receives when the sale price exceeds the minimum they would have accepted. Together with consumer surplus, it measures the gains from exchange.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_834a342788b6aa83199ec2e8', 'Propensity score matching', ARRAY['PSM']::text[], 'A method of pairing treated and untreated observations with similar estimated probabilities of receiving treatment, based on measured characteristics. It cannot remove bias from unmeasured differences.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_652d5a70e330b25776318eb1', 'Property rights', ARRAY[]::text[], 'Legally recognised rights to use, control or transfer an asset, subject to applicable restrictions. Clear property rights can affect incentives to invest and conserve resources.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_23e699eda6ebc47c00e1a0a7', 'Protectionism', ARRAY[]::text[], 'Government policies that restrict imports or favour domestic suppliers, often through tariffs, quotas or non-tariff measures. They may protect particular industries while raising costs for consumers.', 'https://openstax.org/books/principles-economics-3e/pages/34-1-protectionism-an-indirect-subsidy-from-consumers-to-producers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8569a9a7b80d2e712a6954c0', 'Quasi-experiment', ARRAY['quasi-experimental design']::text[], 'A study that seeks to estimate causal effects without assigning treatment purely at random, often by exploiting a policy rule, threshold or natural variation.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d89da18883b836885e149006', 'Random assignment', ARRAY['random allocation']::text[], 'Allocating participants to study groups using a random process, so systematic differences are less likely to determine who receives an intervention.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_732241eb169668a7a7c913e6', 'Randomised controlled trial', ARRAY['randomized controlled trial', 'RCT']::text[], 'A study in which researchers randomly assign eligible participants to receive an intervention or join a comparison group. Random assignment helps isolate the intervention''s causal effect.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9b54b72ca805e192820d9f06', 'Rational ignorance', ARRAY[]::text[], 'A situation in which someone chooses not to acquire detailed information because the expected personal benefit is smaller than the effort or cost involved.', 'https://openstax.org/books/principles-economics-3e/pages/18-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e58920470eea8f98db303ea0', 'Real estate investment trust', ARRAY['REIT']::text[], 'A company or trust that holds or finances income-producing property, often allowing investors to gain property exposure through tradeable securities.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/real-estate-investment-trusts-reits', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4b47d477bd93a3bdf889f11a', 'Real GDP', ARRAY[]::text[], 'The value of economic output adjusted for price changes. It tracks growth in the volume of production rather than inflation.', 'https://openstax.org/books/principles-economics-3e/pages/19-2-adjusting-nominal-values-to-real-values', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_80d232f619414f82515224a4', 'Regression discontinuity design', ARRAY['RDD']::text[], 'A causal research method that compares observations just above and just below a threshold determining treatment eligibility. Near the cutoff, the groups may be otherwise comparable.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9f622f95b43dc135fd9d658d', 'Relative poverty', ARRAY[]::text[], 'A measure of disadvantage based on resources falling substantially below a society''s typical standard of living, often defined relative to median income.', 'https://www.oecd.org/en/topics/inequality-and-poverty.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f49b8db67ea0514b915b5043', 'Reserve requirement', ARRAY[]::text[], 'A rule obliging banks to hold a minimum amount of reserves relative to a specified liability measure, where such requirements apply. Rules vary across monetary systems.', 'https://openstax.org/books/principles-economics-3e/pages/28-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_f136d7b3255513d84944389f', 'Risk-adjusted return', ARRAY[]::text[], 'Investment performance assessed relative to the risk taken to achieve it. Measures differ in which kinds of risk they consider and how they quantify them.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_d5c6bfeed31aa215256f4be4', 'Rules of origin', ARRAY[]::text[], 'Criteria used to determine a product''s economic nationality for customs purposes, including whether it qualifies for a preferential tariff under a trade agreement.', 'https://www.wto.org/english/thewto_e/glossary_e/rules_of_origin_e.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_14c6fc351ad428a4adcb7058', 'Sampling bias', ARRAY[]::text[], 'A distortion arising when the method used to select observations systematically favours some parts of the population, making results unrepresentative.', 'https://openstax.org/books/introductory-statistics-2e/pages/1-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4d572a7a8224433ac0abb06f', 'Sampling distribution', ARRAY[]::text[], 'The probability distribution of a statistic, such as a sample mean, across all possible repeated samples from the same population under the specified sampling method.', 'https://openstax.org/books/introductory-statistics-2e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2ee73a404a750b5b5f64135e', 'Selection bias', ARRAY[]::text[], 'A systematic difference between selected and unselected observations that can make a sample or comparison group unrepresentative and lead to misleading conclusions.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_ac8bc1367de2a019e145a006', 'Share buyback', ARRAY['stock repurchase', 'share repurchase']::text[], 'A transaction in which a company purchases its own shares, potentially returning cash to investors and reducing the number of shares outstanding.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_14bc06889a3bf8559c512dc4', 'Share dilution', ARRAY[]::text[], 'A reduction in existing shareholders'' percentage ownership when a company issues additional shares without corresponding purchases by those holders.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e99adb5fb9a9c26f193829ec', 'Short selling', ARRAY['short sale']::text[], 'Selling a security that an investor has borrowed or arranged to borrow, often hoping to buy it back more cheaply later. Losses can be substantial if the price rises.', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/stock-purchases-and-sales-long-and', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_83fdec950aa8d56b5c02fc7b', 'Simple interest', ARRAY[]::text[], 'Interest calculated only on the original principal, rather than on previously accumulated interest. It increases the balance at a constant amount per period when the rate is fixed.', 'https://openstax.org/books/principles-economics-3e/pages/17-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9e686202dbf32c240e6bd6dd', 'Social cost', ARRAY[]::text[], 'The total cost of an activity to society, including the private costs borne by participants and external harms imposed on others.', 'https://openstax.org/books/principles-economics-3e/pages/12-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c21475ae2b9f82c16c292be1', 'Social safety net', ARRAY['social protection safety net']::text[], 'Public programmes that help people facing low income or financial shocks, such as means-tested benefits, unemployment support and certain food or housing schemes.', 'https://openstax.org/books/principles-economics-3e/pages/15-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_e4dea97ac9522abd712fafaf', 'Social surplus', ARRAY['total surplus', 'economic surplus']::text[], 'The total gains that consumers and producers receive from market exchange. In a simple supply-and-demand model, it equals consumer surplus plus producer surplus.', 'https://openstax.org/books/principles-economics-3e/pages/3-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_aec8923c1e13dd958e977d36', 'Soft currency peg', ARRAY['soft peg']::text[], 'An exchange rate arrangement in which authorities allow some movement in the currency but sometimes intervene to limit fluctuations or guide its value.', 'https://openstax.org/books/principles-economics-3e/pages/29-4-exchange-rate-policies', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_78151e1127b852e5fad3b3b6', 'Sovereign debt', ARRAY[]::text[], 'Borrowing owed by a national government, often through government bonds or loans. It can fund spending and investment but creates repayment obligations.', 'https://www.imf.org/en/publications/fandd/issues/2022/12/basics-what-is-sovereign-debt', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_39ad22151a73d37b07b18cba', 'Special economic zone', ARRAY['SEZ']::text[], 'A designated area with distinct business, customs or tax arrangements designed to attract investment and trade. The rules and outcomes vary substantially across countries.', 'https://openstax.org/books/principles-economics-3e/pages/20-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_70122e6380205ddb985968a5', 'Standard deviation', ARRAY[]::text[], 'A measure of how dispersed observations are around their average, expressed in the same units as the data. A larger standard deviation indicates greater variability.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_17ddafdd98fb1565f1408d0b', 'Standard error', ARRAY[]::text[], 'The standard deviation of the sampling distribution of an estimated quantity. It indicates how much an estimate would typically vary across repeated samples.', 'https://openstax.org/books/introductory-statistics-2e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_0b21fb4eea3a4b9f3b5f6a79', 'Statistical significance', ARRAY[]::text[], 'A description of evidence considered unlikely under a specified null hypothesis at a chosen testing threshold. Statistical significance alone does not establish practical importance or causation.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6f0e7514ab9ee92b5f3b2864', 'Stock split', ARRAY['share split']::text[], 'A change that increases the number of shares held by investors while reducing the price per share proportionately, without changing each investor''s ownership percentage by itself.', 'https://www.investor.gov/introduction-investing/investing-basics/glossary/stock-split', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_4ff15aba420a3eb197106990', 'Stop-loss order', ARRAY['stop order']::text[], 'An order that becomes eligible for execution when a security reaches a specified trigger price. It may execute at a different price from the trigger during volatile markets.', 'https://www.investor.gov/introduction-investing/investing-basics/how-stock-markets-work/types-orders', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_bec03a5557ec0d58aecef439', 'Structural budget balance', ARRAY['structural balance']::text[], 'An estimate of the government''s underlying budget position after adjusting for the economic cycle and certain temporary factors. It depends on uncertain estimates of potential output.', 'https://www.elibrary.imf.org/display/book/9798229042512/CH003.xml', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_aff4e4aad7e641b031c8f8e8', 'Structural unemployment', ARRAY[]::text[], 'Joblessness arising when workers'' skills or locations do not match the jobs employers need. It may persist even when the wider economy is growing.', 'https://openstax.org/books/principles-economics-3e/pages/21-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_383fb68514eada4a60d4d503', 'Substitution bias', ARRAY[]::text[], 'A distortion in a fixed-basket price index when consumers switch away from goods that become relatively expensive. Ignoring substitution can overstate changes in the cost of living.', 'https://openstax.org/books/principles-economics-3e/pages/22-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_900802e1ac21a946fe9163a4', 'Substitution effect', ARRAY[]::text[], 'The change in a consumer''s chosen quantities caused by a change in relative prices, holding utility constant. It differs from the purchasing-power effect of a price change.', 'https://openstax.org/books/principles-economics-3e/pages/6-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1704364aa21cc249f7f5882c', 'Tax incidence', ARRAY[]::text[], 'How the economic burden of a tax is shared between buyers and sellers, regardless of which side legally pays it. The less price-responsive side generally bears more of the burden.', 'https://openstax.org/books/principles-economics-3e/pages/5-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1f1ff42aadb1760162eb8c7e', 'Trade barrier', ARRAY['trade barriers']::text[], 'A policy or practice that increases the cost of cross-border trade or restricts its volume. Barriers can include tariffs, quotas and regulatory requirements.', 'https://openstax.org/books/principles-economics-3e/pages/34-1-protectionism-an-indirect-subsidy-from-consumers-to-producers', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b55c99569a8bedfcb6d8144b', 'Trade dumping', ARRAY['dumping in trade']::text[], 'The export of goods at a price below a legally defined normal value, often linked to the home-market price. Dumping is not itself identical to unlawful predatory pricing.', 'https://www.wto.org/english/thewto_e/minist_e/min96_e/glossary.htm', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_b52f5d2434b93d01c383975b', 'Trade liberalisation', ARRAY['trade liberalization']::text[], 'The reduction of tariffs, quotas and other barriers to cross-border commerce. It can increase competition and trade while creating adjustment costs for affected workers and firms.', 'https://openstax.org/books/principles-economics-3e/pages/34-4-how-governments-enact-trade-policy-globally-regionally-and-nationally', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_1f8a0ed4e8413dd51b6b01de', 'Trade union', ARRAY['labor union', 'labour union']::text[], 'An organisation representing workers'' collective interests, including negotiating pay and working conditions and providing support in workplace disputes.', 'https://openstax.org/books/principles-economics-3e/pages/14-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9dc6276869e3897598758046', 'Treatment group', ARRAY[]::text[], 'The group of participants in an experiment or evaluation that receives the intervention being studied. Its outcomes are compared with those of an appropriate control or comparison group.', 'https://www.worldbank.org/en/programs/sief-trust-fund/publication/impact-evaluation-in-practice', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_c9c413d898fde807deaf2136', 'Type I error', ARRAY['false positive hypothesis test']::text[], 'Rejecting a statistical null hypothesis when it is actually true. The significance threshold sets the maximum probability of this error under the testing assumptions.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_2735c56a04f900a25305be03', 'Type II error', ARRAY['false negative hypothesis test']::text[], 'Failing to reject a statistical null hypothesis when it is false. The probability of avoiding this error is related to a test''s statistical power.', 'https://openstax.org/books/introductory-statistics-2e/pages/9-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_9fda2d694417f731959b4398', 'Unilateral transfer', ARRAY['unilateral transfers']::text[], 'A payment or transfer across borders for which no good, service or asset is received in exchange, such as certain remittances or aid grants.', 'https://openstax.org/books/principles-economics-3e/pages/23-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_343b5f82f21b70453b510da1', 'Variable cost', ARRAY[]::text[], 'A production expense that changes with output, such as raw materials needed for additional units. Total variable costs generally rise as output expands.', 'https://openstax.org/books/principles-economics-3e/pages/7-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_6d4bc2ac3367c2581f40a9ac', 'Venture capital', ARRAY[]::text[], 'Investment financing provided to young or rapidly growing businesses with uncertain outcomes and potential for substantial growth, generally in exchange for equity.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/private-investment-funds/private-equity-funds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_68cb267887732e8a7da30ec9', 'Voluntary carbon market', ARRAY['VCM']::text[], 'A market where firms or individuals trade carbon credits outside mandatory emissions trading obligations, often to support voluntary climate commitments.', 'https://ppp.worldbank.org/emission-reduction-credits', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_8054701dc9ceafb75c01c754', 'Voting cycle', ARRAY[]::text[], 'A pattern of collective preferences in which a majority favours option A over B, B over C, but C over A. It shows why majority voting can lack a stable winner.', 'https://openstax.org/books/principles-economics-3e/pages/18-key-terms', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_407e56653dfb6222dc7527e0', 'Wealth inequality', ARRAY[]::text[], 'Differences in the distribution of accumulated assets minus debts among people or households. It can be substantially greater than inequality in annual income.', 'https://www.oecd.org/en/topics/inequality-and-poverty.html', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_525478e08abbcf9f53282283', 'Yield to maturity', ARRAY['YTM']::text[], 'The annualised return implied by a bond''s current market price and promised payments if it is held to maturity and all contractual payments are made, under the calculation assumptions.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc')),
  ('cg26_a8c3a0c69da25c486c0a0819', 'Zero-coupon bond', ARRAY[]::text[], 'A bond that makes no regular interest payments and is generally issued or traded below its face value. The difference between purchase price and redemption value contributes to its return.', 'https://www.investor.gov/introduction-investing/investing-basics/investment-products/bonds-or-fixed-income-products/bonds', true, (now() AT TIME ZONE 'utc'), (now() AT TIME ZONE 'utc'))
